{"implementation":"def solve(case):
    text = case['text']
    passes = case['passes']
    max_rounds = case['max_rounds']
    trace = []
    for _ in range(max_rounds):
        changed = False
        for p in passes:
            old = p['old']
            new = p['new']
            if old in text:
                text = text.replace(old, new, 1)
                trace.append(p['name'])
                changed = True
        if not changed:
            return {'artifact': text, 'trace': trace, 'fixed_point': True}
    return {'artifact': text, 'trace': trace, 'fixed_point': False}"}
